import React from "react";
import { useTranslation } from "react-i18next";
import images from "../images";
import data from "../data/data.json";

// Define the ProductIntro type based on usage
type ProductIntro = {
  subtitle?: string;
  item?: string;
};

// Define the IconCertificate type based on usage
type IconCertificate = {
  image?: string;
};

const ProductDisplay = () => {
const { t } = useTranslation();

const categories =
  (t("products.items", { returnObjects: true }) as Array<any>) || [];

  return (
    <section className="text-DeepSea">
  {categories.map((category, catIndex) => (
    <div key={catIndex} className="pt-8 sm:pt-32" id={data.submenuProducts[catIndex]}>

      {category.products?.map((product: any) => (
        <div
          key={product.id}
          className="flex flex-col sm:flex-row w-full mx-auto border-b border-DeepSea py-12"
        >
          <div className="w-full sm:w-1/2">
            <img src={`/${product.iconDivision}.svg`} className="h-[30px] sm:h-[42px]" />
            <h2
              className="head-3 sm:head-2 text-DeepSea py-6"
              dangerouslySetInnerHTML={{ __html: product.name }}
            />

            <div className="body-3 sm:body-1">
              {product.intro.map((intro: ProductIntro, idx: number) =>
                intro.item ? (
                  <div key={idx}>
                    {intro.subtitle && (
                      <strong className="">{intro.subtitle}</strong>
                    )}
                    <p dangerouslySetInnerHTML={{ __html: intro.item }} />
                  </div>
                ) : null
              )}
            </div>

            {product.iconCertificate && (
              <div className="flex space-x-4 mt-6 sm:mt-0 mb-6">
                {product.iconCertificate.map(
                  (cert: IconCertificate, idx: number) => {
                    if (!cert.image) return null;
                    const imageData = images[cert.image];
                    return imageData ? (
                      <img
                        key={idx}
                        src={imageData.src}
                        alt={imageData.alt || `Certificate ${idx + 1}`}
                        className="w-12 h-12 object-contain"
                      />
                    ) : null;
                  }
                )}
              </div>
            )}

          </div>

          <aside className="w-full sm:w-1/2 pl-0 sm:pl-48 space-y-6 body-3 sm:body-2 pt-4">
            {product.aside.intro.map((text: ProductIntro, idx: number) =>
              text.item ? <p key={idx}>{text.item}</p> : null
            )}

            {product.aside.applications.length > 1 && (
              <div className="pt-6">
                <h3 className="head-6 sm:head-5 text-DeepSea">Applications</h3>
                <ul className={styles.lists}>
                  {product.aside.applications.map(
                    (app: ProductIntro, idx: number) =>
                      app.item ? (
                        <li
                          className={styles.listItems}
                          key={idx}
                          dangerouslySetInnerHTML={{ __html: app.item }}
                        />
                      ) : null
                  )}
                </ul>
              </div>
            )}

            {product.aside.keyFeatures.length > 1 && (
              <div className="pt-6">
                <h3 className="head-6 sm:head-5 text-DeepSea">Key Features</h3>
                <ul className={styles.lists}>
                  {product.aside.keyFeatures.map(
                    (feature: ProductIntro, idx: number) =>
                      feature.item ? (
                        <li
                          className={styles.listItems}
                          key={idx}
                          dangerouslySetInnerHTML={{ __html: feature.item }}
                        />
                      ) : null
                  )}
                </ul>
              </div>
            )}

            {product.aside.keyBenefits.length > 1 && (
              <div className="pt-6">
                <h3 className="head-6 sm:head-5 text-DeepSea">Key Benefits</h3>
                <ul className={styles.lists}>
                  {product.aside.keyBenefits.map(
                    (benefit: ProductIntro, idx: number) =>
                      benefit.item ? (
                        <li
                          className={styles.listItems}
                          key={idx}
                          dangerouslySetInnerHTML={{ __html: benefit.item }}
                        />
                      ) : null
                  )}
                </ul>
              </div>
            )}
          </aside>
        </div>
      ))}

    </div>
  ))}
    </section>
  );
};

export default ProductDisplay;


const styles = {
  lists : "list-disc mt-4 sm:mt-6",
  listItems: "my-2 ml-8 pl-2"
}
